def solve(g):
    h,w=len(g),len(g[0])
    pts={(i,j):g[i][j] for i in range(h) for j in range(w) if g[i][j]!=g[0][0]}
    out=[row[:] for row in g]
    segs=[]
    for orient,key,span in (('d1',lambda i,j:j-i,lambda ps: ps),('d2',lambda i,j:i+j,lambda ps: sorted(ps,key=lambda p:p[0]))):
        lines={}
        for (i,j),c in pts.items(): lines.setdefault(key(i,j),[]).append((i,j))
        for d,ps0 in lines.items():
            ps=span(ps0)
            if len(ps)>=2:
                (i1,j1),(i2,j2)=ps[0],ps[-1]
                c1,c2=pts[(i1,j1)],pts[(i2,j2)]
                if c1!=c2: continue
                if orient=='d1':
                    cells=[(i,j) for i in range(h) for j in range(w) if j-i==d and j1<=j<=j2]
                else:
                    cells=[(i,j) for i in range(h) for j in range(w) if i+j==d and i1<=i<=i2]
                segs.append((orient,cells,c1))
                for (i,j) in cells:
                    if (i,j) not in pts: out[i][j]=c1
    for (i,j),c in pts.items():
        for o,cells,col in segs:
            if (i,j) in cells and col!=c:
                if o=='d2':  # perpendicular is d1: j-i const
                    for ii in range(h):
                        jj=j-i+ii
                        if 0<=jj<w and (ii,jj) not in pts: out[ii][jj]=c
                else:        # perpendicular is d2: i+j const
                    k=i+j
                    for ii in range(h):
                        jj=k-ii
                        if 0<=jj<w and (ii,jj) not in pts: out[ii][jj]=c
                break
    return out
